import Link from "next/link";
import { AlertTriangle, ArrowRight, BrickWall, Grid3x3, Hammer, House, Info, PaintRoller, Shovel, Thermometer } from "lucide-react";
import type { CalculatorDefinition, CategorySlug } from "@/lib/calculators/types";
import { absoluteUrl } from "@/lib/site";

/** Render a JSON-LD script. Content is generated by us from trusted data. */
export function JsonLd({ data }: { data: Record<string, unknown> }) {
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data).replace(/</g, "\\u003c") }} />;
}

export interface Crumb {
  name: string;
  href: string;
}

export function Breadcrumbs({ items }: { items: Crumb[] }) {
  const all = [{ name: "Home", href: "/" }, ...items];
  return (
    <>
      <nav aria-label="Breadcrumb" className="text-sm text-ink-muted">
        <ol className="flex flex-wrap items-center gap-1.5">
          {all.map((c, i) => (
            <li key={c.href} className="flex items-center gap-1.5">
              {i > 0 && <span aria-hidden>/</span>}
              {i === all.length - 1 ? (
                <span aria-current="page" className="text-ink-soft">
                  {c.name}
                </span>
              ) : (
                <Link href={c.href} className="hover:text-brand-700 hover:underline">
                  {c.name}
                </Link>
              )}
            </li>
          ))}
        </ol>
      </nav>
      <JsonLd
        data={{
          "@context": "https://schema.org",
          "@type": "BreadcrumbList",
          itemListElement: all.map((c, i) => ({ "@type": "ListItem", position: i + 1, name: c.name, item: absoluteUrl(c.href) })),
        }}
      />
    </>
  );
}

const CATEGORY_ICONS: Record<CategorySlug, typeof BrickWall> = {
  concrete: BrickWall,
  landscaping: Shovel,
  flooring: Grid3x3,
  roofing: House,
  carpentry: Hammer,
  painting: PaintRoller,
  insulation: Thermometer,
};

export function CategoryIcon({ category, className = "size-5" }: { category: CategorySlug; className?: string }) {
  const Icon = CATEGORY_ICONS[category];
  return <Icon aria-hidden className={className} />;
}

export function CalculatorCard({ calc }: { calc: CalculatorDefinition }) {
  return (
    <Link
      href={`/${calc.slug}`}
      className="card group flex h-full flex-col gap-3 p-5 transition-shadow hover:border-brand-200 hover:shadow-[var(--shadow-raised)]"
    >
      <span className="flex size-10 items-center justify-center rounded-lg bg-brand-50 text-brand-700">
        <CategoryIcon category={calc.category} />
      </span>
      <span className="font-display text-base font-bold text-ink group-hover:text-brand-700">{calc.title}</span>
      <span className="text-sm leading-relaxed text-ink-muted">{calc.summary}</span>
      <span className="mt-auto inline-flex items-center gap-1 text-sm font-semibold text-brand-700">
        Open calculator <ArrowRight aria-hidden className="size-4 transition-transform group-hover:translate-x-0.5" />
      </span>
    </Link>
  );
}

export function Callout({ tone = "info", title, children }: { tone?: "info" | "warning"; title?: string; children: React.ReactNode }) {
  const styles = tone === "warning" ? "border-amber-400 bg-[#fff8e6] text-ink" : "border-brand-200 bg-brand-50 text-ink";
  const Icon = tone === "warning" ? AlertTriangle : Info;
  return (
    <aside className={`flex gap-3 rounded-xl border-l-4 p-4 text-sm leading-relaxed ${styles}`}>
      <Icon aria-hidden className={`mt-0.5 size-5 shrink-0 ${tone === "warning" ? "text-amber-700" : "text-brand-700"}`} />
      <div>
        {title && <p className="font-semibold">{title}</p>}
        <div className={title ? "mt-1 text-ink-soft" : "text-ink-soft"}>{children}</div>
      </div>
    </aside>
  );
}

export function PageHeader({ eyebrow, title, intro }: { eyebrow?: string; title: string; intro?: React.ReactNode }) {
  return (
    <div className="max-w-3xl">
      {eyebrow && <p className="text-sm font-semibold uppercase tracking-wider text-brand-700">{eyebrow}</p>}
      <h1 className="mt-2 text-3xl font-extrabold leading-tight sm:text-4xl">{title}</h1>
      {intro && <div className="mt-4 text-lg leading-relaxed text-ink-soft">{intro}</div>}
    </div>
  );
}
